nextflow_process {
    name "MOSDEPTH"
    script "../main.nf"
    process "MOSDEPTH"

    test("targeted coverage") {
        options "-with-docker"

        when {
            process {
                """
                input[0] = record(
                    id: 'sample',
                    bam: file("${moduleDir}/tests/data/reads.bam", checkIfExists: true),
                    bai: file("${moduleDir}/tests/data/reads.bam.bai", checkIfExists: true),
                    ref: file("${moduleDir}/tests/data/reference.fa", checkIfExists: true),
                    fai: file("${moduleDir}/tests/data/reference.fa.fai", checkIfExists: true)
                )
                input[1] = file("${moduleDir}/tests/data/target.bed", checkIfExists: true)
                input[2] = true
                """
            }
        }

        then {
            assert process.success
            assert file(process.out[0].target[0]).text.trim() == 'chr1\t1100\t1400'
            assert file(process.out[0].summary[0]).text.contains('total')
            assert file(process.out[0].global_dist[0]).text.contains('total')
            assert file(process.out[0].region_dist[0]).text.contains('total')
            assert new File(process.out[0].regions[0].toString()).isFile()
            assert new File(process.out[0].regions_index[0].toString()).isFile()
        }
    }
}
